patch.css:
/* Lanternwake Harbor — a weathered harbor inn.
Shape spec: small-round plaster containers 8px; nested drawers, fields and buttons 4px; native tags and avatars retained; Conversation bubbles retain native silhouette.
Borders: containers 3px double rope-coloured theme border, fields/buttons 1px solid. Shadows: soft inset lantern glow only. Selected: warm fill and inset ring; focus: inset ring. No added phone rows, repositioned controls, animation, or decorative overlays. */
:root {
 --mari-tokens-version: 1; --radius: 0.5rem; --mari-font-ui: system-ui, sans-serif; --mari-font-heading: Georgia, serif; --mari-font-chat: system-ui, sans-serif; --mari-message-measure: 70ch;
 --mari-selected-tint: var(--primary); --mari-page-veil: var(--background); --mari-top-bar-plate: var(--card); --mari-top-bar-plate-active: var(--secondary); --mari-top-bar-plate-radius: 4px; --mari-accent-text: var(--primary);
 --mari-app-backdrop: url("theme:harbor-day-background.webp"); --mari-top-bar-bg: url("theme:harbor-day-header.webp") center / cover no-repeat;
 --mari-app-backdrop-position: center; --mari-app-backdrop-size: cover;
 --mari-app-backdrop-layers: var(--mari-app-backdrop) center / cover no-repeat;
 --mari-dialogue-color: var(--card-foreground);
 --ov-text: var(--foreground); --ov-muted: var(--muted-foreground); --ov-dim: var(--muted-foreground); --ov-line: var(--border); --ov-accent: var(--primary); --ov-hover: var(--accent); --ov-active-bg: var(--secondary);
 --mari-weather-style: smooth; --mari-weather-amount: 0.65; --mari-weather-speed: 0.8; --mari-weather-strength: 1; --mari-weather-tint-strength: 0.65; --mari-weather-rain-color: #5896b3; --mari-weather-rain-length: 1.3; --mari-weather-snow-color: #d8eaf1; --mari-weather-snow-size: 1.1; --mari-weather-fog-color: #b6cbd0; --mari-weather-sun-color: #ffe2a1; --mari-weather-moon-color: #ffedc9;
}
:root, :root[data-theme="light"], :root[data-mari-sky="day"], :root[data-mari-sky="dawn"] {
 --background: #eaf3f2; --foreground: #173c48; --card: #fffaf0; --card-foreground: #173c48; --popover: #fffaf0; --popover-foreground: #173c48; --primary: #086780; --primary-foreground: #ffffff; --secondary: #f3dfb6; --secondary-foreground: #173c48; --muted: #e3edeb; --muted-foreground: #4c6870; --accent: #f4e6ca; --accent-foreground: #173c48; --border: #927b53; --input: #7899a0; --ring: #086780; --sidebar: #f3f3e9; --sidebar-foreground: #173c48; --sidebar-border: #927b53; --sidebar-accent: #f3dfb6; --sidebar-accent-foreground: #173c48; --destructive: #a52f2f; --destructive-foreground: #ffffff;
}
:root[data-theme="dark"]:not([data-mari-sky="day"]):not([data-mari-sky="dawn"]), :root[data-mari-sky="night"], :root[data-mari-sky="dusk"] {
 --background: #101e28; --foreground: #f5ead5; --card: #1a2b34; --card-foreground: #f5ead5; --popover: #1a2b34; --popover-foreground: #f5ead5; --primary: #edbc77; --primary-foreground: #29200f; --secondary: #51412e; --secondary-foreground: #f5ead5; --muted: #253942; --muted-foreground: #bfd0cf; --accent: #443c30; --accent-foreground: #fff0d6; --border: #a28b63; --input: #839695; --ring: #edbc77; --sidebar: #15252e; --sidebar-foreground: #f5ead5; --sidebar-border: #a28b63; --sidebar-accent: #51412e; --sidebar-accent-foreground: #f5ead5; --destructive: #ffb0a1; --destructive-foreground: #331a18;
 --mari-app-backdrop: url("theme:harbor-night-background.webp"); --mari-top-bar-bg: url("theme:harbor-night-header.webp") center / cover no-repeat; --mari-weather-rain-color: #a6c6d4;
}
:root[data-mari-weather="rain"], :root[data-mari-weather="storm"] { --mari-weather-tint-strength: 0.85; --mari-app-backdrop-layers: linear-gradient(#102c4866,#102c4866), var(--mari-app-backdrop) center / cover no-repeat; }
:root[data-mari-weather="snow"] { --mari-app-backdrop-layers: linear-gradient(#d7edf333,#aecbd144), var(--mari-app-backdrop) center / cover no-repeat; }
:root[data-mari-weather="fog"] { --mari-weather-tint-strength: 0.95; --mari-app-backdrop-layers: linear-gradient(#b6cbd077,#b6cbd0aa), var(--mari-app-backdrop) center / cover no-repeat; }
/* Opaque plaster with faint mineral grain. The texture is paint, never a layer over controls. */
[data-mari-part="page"], [data-mari-part="home-widget"], .mari-window, .mari-drawer, [data-mari-part="bubble"], [data-mari-part="composer"] {
 background-color: var(--card);
 background-image: repeating-linear-gradient(117deg, transparent 0 11px, color-mix(in srgb, var(--border) 5%, transparent) 11px 12px), linear-gradient(155deg, color-mix(in srgb, var(--secondary) 20%, transparent), transparent 65%);
 color: var(--card-foreground); border: 3px double var(--border); border-radius: 8px;
 box-shadow: inset 0 0 14px color-mix(in srgb, var(--secondary) 35%, transparent);
}
.mari-drawer { border-radius: 4px; }
:root[data-chat-open-mode="conversation"] [data-mari-part="bubble"] { border-radius: revert-layer; }
/* A message row is not a second bubble. */
[data-mari-part="message"] { background: transparent; border: 0; box-shadow: none; }
.mari-window__header { border-radius: 5px 5px 0 0; }
.mari-drawer__header { border-radius: 1px 1px 0 0; }
.mari-window__header, .mari-drawer__header { background: var(--secondary); color: var(--secondary-foreground); border-bottom: 1px solid var(--border); }
[data-mari-part="page-title"], [data-mari-part="home-widget-title"], .mari-window__title, .mari-drawer__title { font-family: var(--mari-font-heading); color: var(--foreground); }
:where(button,input,select,textarea), .mari-window__control, .mari-drawer__popout { border-radius: 4px; }
:where(input,select,textarea) { background-color: var(--card); color: var(--foreground); border: 1px solid var(--input); }
:where(input,textarea)::placeholder { color: var(--muted-foreground); opacity: 1; }
:where(button,[role="tab"])[aria-selected="true"], button[aria-pressed="true"], .mari-window-bubble[data-open="true"] {
 background: var(--secondary); color: var(--secondary-foreground); box-shadow: inset 0 0 0 1px var(--border), inset 0 0 12px color-mix(in srgb, var(--primary) 20%, transparent);
}
:where(button,input,select,textarea,a,[role="tab"]):focus-visible { outline: 2px solid var(--ring); outline-offset: -3px; }
/* Opaque plates isolate labels from the artwork at every crop. Internal top-bar classes are documented but may change; paint only. */
[data-mari-part="top-bar"] :is(button,[role="tab"],.ov-tab,.ov-icon-btn) { background-color: var(--card); color: var(--card-foreground); border-radius: 4px; box-shadow: inset 0 0 0 1px var(--border); }
[data-mari-part="top-bar"] :is([aria-selected="true"],[aria-pressed="true"]) { background-color: var(--secondary); color: var(--secondary-foreground); box-shadow: inset 0 0 0 2px var(--border), inset 0 0 12px color-mix(in srgb, var(--primary) 20%, transparent); }
@media (hover:hover) {
 [data-mari-part="home-widget"]:hover { border-color: var(--primary); }
 [data-mari-part="top-bar"] :is(button,[role="tab"],.ov-tab,.ov-icon-btn):hover { background-color: var(--accent); color: var(--accent-foreground); }
}
@media (prefers-contrast: more) {
 [data-mari-part="page"], [data-mari-part="home-widget"], .mari-window, .mari-drawer, [data-mari-part="bubble"], [data-mari-part="composer"] { background-image: none; box-shadow: none; }
}
:root[data-mari-contrast="more"] :is([data-mari-part="page"],[data-mari-part="home-widget"],.mari-window,.mari-drawer,[data-mari-part="bubble"],[data-mari-part="composer"]) { background-image: none; box-shadow: none; }
/* Native phone layout, toolbar heights, accessibility typography and weather behaviour remain intact. */

